CREATE TABLE "Notification" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"actorId" TEXT NOT NULL,"type" TEXT NOT NULL,"postId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"readAt" TIMESTAMP(3),CONSTRAINT "Notification_pkey" PRIMARY KEY ("id"),CONSTRAINT "Notification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE,CONSTRAINT "Notification_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE CASCADE,CONSTRAINT "Notification_postId_fkey" FOREIGN KEY ("postId") REFERENCES "Post"("id") ON DELETE CASCADE);
CREATE INDEX "Notification_userId_createdAt_idx" ON "Notification"("userId","createdAt");
